-- Odoo under ~/Projects/odoo:
--   odools.toml at the root (generated by odoo-lsconf, one profile per client)
--   clients/<name>/{.odoo-version, odoo.conf, .venv, .pylintrc?}
-- odoo-ls owns Python there (no pyright), no format-on-save in company repos,
-- pylint-odoo runs from the client's own venv.

local function odoo_root(src)
  return vim.fs.root(src, { "odools.toml" })
end

local function client_dir(path)
  local f = vim.fs.find(".odoo-version", { upward = true, path = path, limit = 1 })[1]
  return f and vim.fs.dirname(f)
end

return {
  {
    "odoo/odoo-neovim",
    ft = { "python", "xml", "csv", "javascript", "typescript" },
    cmd = "OdooLs",
    -- profile = the client nvim was started in (`onv <client>` cds there); otherwise idle
    opts = function()
      local c = client_dir(vim.fn.getcwd())
      return { profile = c and vim.fs.basename(c) or "Disabled" }
    end,
    init = function()
      -- company repos: never reformat on save (<leader>cf still works on demand)
      vim.api.nvim_create_autocmd("FileType", {
        pattern = { "python", "xml", "javascript", "csv" },
        callback = function(ev)
          if odoo_root(ev.buf) then
            vim.b[ev.buf].autoformat = false
          end
        end,
      })
    end,
  },

  {
    "neovim/nvim-lspconfig",
    opts = {
      servers = {
        -- pyright only outside ~/Projects/odoo; odoo-ls understands Odoo models there
        pyright = {
          root_dir = function(bufnr, on_dir)
            if odoo_root(bufnr) then
              return
            end
            local f = vim.api.nvim_buf_get_name(bufnr)
            on_dir(vim.fs.root(f, {
              "pyrightconfig.json",
              "pyproject.toml",
              "setup.py",
              "setup.cfg",
              "requirements.txt",
              "Pipfile",
              ".git",
            }) or vim.fs.dirname(f))
          end,
        },
      },
    },
  },

  {
    "mfussenegger/nvim-lint",
    opts = function(_, opts)
      opts.linters_by_ft = opts.linters_by_ft or {}
      opts.linters_by_ft.python = { "pylint" }
      local pylint = require("lint").linters.pylint
      if pylint._odoo then
        return
      end -- opts can run more than once
      pylint._odoo = true
      local function venv_pylint(file)
        local c = client_dir(vim.fs.dirname(file))
        local bin = c and (c .. "/.venv/bin/pylint")
        return bin and vim.uv.fs_stat(bin) and bin
      end
      -- only in client workspaces whose venv has pylint (+ pylint-odoo)
      pylint.condition = function(ctx)
        return venv_pylint(ctx.filename) ~= nil
      end
      pylint.cmd = function()
        return venv_pylint(vim.api.nvim_buf_get_name(0))
      end
      -- nearest .pylintrc wins (repo's own before the client's)
      table.insert(pylint.args, 1, function()
        local file = vim.api.nvim_buf_get_name(0)
        local rc = vim.fs.find(
          ".pylintrc",
          { upward = true, path = vim.fs.dirname(file), stop = vim.fs.dirname(client_dir(vim.fs.dirname(file)) or "/") }
        )[1]
        return "--rcfile=" .. (rc or "/dev/null")
      end)
    end,
  },
}
